				array[j] = Math.Max(array[j], FormatHelper.RenderInlinePlainText(row[j]).Length);
			}
		}
		for (int k = 0; k < headers.Length; k++)
		{
			if (k < headers.Length - 1)
			{
				w.Write(headers[k].PadRight(array[k] + 2));
			}
			else
			{
				w.Write(headers[k]);
			}
		}
		w.WriteLine();
		for (int l = 0; l < headers.Length; l++)
		{
			if (l < headers.Length - 1)
			{
				w.Write(new string('-', array[l]).PadRight(array[l] + 2));
			}
			else
			{
				w.Write(new string('-', array[l]));
			}
		}
		w.WriteLine();
		foreach (string[] row2 in rows)
		{
			for (int m = 0; m < row2.Length; m++)
			{
				if (m < row2.Length - 1)
				{
					w.Write(FormatHelper.RenderInlinePlainText(row2[m]).PadRight(array[m] + 2));
				}
				else
				{
					w.Write(FormatHelper.RenderInlinePlainText(row2[m]));
				}
			}
			w.WriteLine();
		}
		if (skippedRows > 0)
		{
			w.WriteLine($"\n... and {skippedRows} more");
		}
	}

