	{
		w.Write(item.Term);
		w.Write(": ");
		w.WriteLine(FormatHelper.RenderInlinePlainText(item.Text));
		if (item.Detail != null)
		{
			w.Write("  ");
			w.WriteLine(FormatHelper.RenderInlinePlainText(item.Detail));
