    private List<Dep> _dependencies = new();

    public PackageDeps() { }

    public PackageDeps(string id, List<Dep> dependencies)
    {
        Id = id;
        _dependencies = dependencies;
    }

    private bool HasMixedOptional => _dependencies.Any(d => d.Optional);

    [MarkoutSection(Name = "Dependencies")]
    public List<DepDisplay> Dependencies 
    {
        get => _dependencies.Select(d => new DepDisplay 
        { 
            Name = d.Name, 
            Version = d.Version,
            Optional = HasMixedOptional ? d.Optional : (bool?)null
        }).ToList();
    }
}

