static void RenderTree(TreeNode node, string prefix, bool isLast)
{
    var connector = isLast ? "└── " : "├── ";
    var badge = !string.IsNullOrEmpty(node.Badge) ? $" {node.Badge}" : "";
    Console.WriteLine(prefix + connector + node.Name + badge);

    var newPrefix = prefix + (isLast ? "    " : "│   ");
    for (int i = 0; i < node.Children.Count; i++)
    {
        RenderTree(node.Children[i], newPrefix, i == node.Children.Count - 1);
    }
}

