    markdown.AppendLine($"| {metric.Name} | {metric.Before} | {metric.After} | {status} |");
}

Console.WriteLine(markdown.ToString());

static string EvaluateMetric<T>(MetricChange<T> metric) where T : IComparable<T>
{
    var comparison = metric.After.CompareTo(metric.Before);
    return metric.Goal switch
    {
        Goal.Lower => comparison < 0 ? "✅ Good" : (comparison > 0 ? "❌ Bad" : "→ No change"),
        Goal.Higher => comparison > 0 ? "✅ Good" : (comparison < 0 ? "❌ Bad" : "→ No change"),
        _ => "❓ Unknown",
    };
}"}

