static void RenderReport(SearchReport report, string format)
{
    Console.WriteLine($"\n=== Format: {format.ToUpper()} ===\n");

    var stringWriter = new StringWriter();
    var writer = format switch
    {
        "md" => new MarkoutWriter(
            stringWriter,
            new MarkdownFormatter(),
            new MarkoutWriterOptions { MaxTableRows = 3 }
        ),
        "tsv" => new MarkoutWriter(
            stringWriter,
            new TableFormatter(MarkoutTableMode.Tsv),
            new MarkoutWriterOptions()
        ),
        "jsonl" => new MarkoutWriter(
            stringWriter,
            new TableFormatter(MarkoutTableMode.Jsonl),
            new MarkoutWriterOptions()
        ),
        _ => throw new ArgumentException($"Unknown format: {format}")
    };

    MarkoutSerializer.Serialize(report, writer, ReportContext.Default);
    Console.Write(stringWriter.ToString());
}

