var report = new PackageReport
{
    Id = pkg.Id,
    Downloads = pkg.Downloads,
    Signed = pkg.Signed,
    Deprecations = pkg.Deprecations.Count > 0 ? pkg.Deprecations : null,
    Dependencies = pkg.Dependencies.Count > 0 ? new() : null,
    Signals = pkg.Signals.Count > 0 ? pkg.Signals : null,
};

